tool_input_args.value:
cd /workspace && awk -F',' 'NR>1 {
  total += $5
  status[$7] += $5
  count[$7]++
}
END {
  printf "=== Q3 Sales Summary — Meridian Analytics ===\n\n"
  printf "Grand Total (all deals):  $%\047.2f  (%d deals)\n\n", total, NR-1
  printf "%-10s %8s %12s\n", "Status", "Deals", "Amount"
  printf "%-10s %8s %12s\n", "------", "-----", "------"
  for (s in status) printf "%-10s %8d %12s\n", s, count[s], sprintf("$%\047.2f", status[s])
  printf "\n"
}' data/sales_q3.csv
